    "desc": "관광지에서 조금 떨어진 미야즈 시가지에 있는 작은 목조 성당. 1896년에 지어져, 현재도 미사를 드리는 목조 교회로는 일본에서 가장 오래된 것으로 전해진다. 로마네스크풍 외관 안으로 들어서면 바닥이 다다미로 깔린 독특한 화양절충 공간이 나온다 — 신발을 벗고 다다미에 앉아 스테인드글라스를 올려다보는 경험은 이 도시에서만 가능하다. 2024년 국가 중요문화재로 지정됐다.",
